/// The product of two `GF(2^8)` elements, in the tower representation.
#[inline]
pub(crate) const fn mul(a: u8, b: u8) -> u8 {
    let exponent = LOG[a as usize] as usize + LOG[b as usize] as usize;
    // The sentinel at `LOG[0]` is not a logarithm, so the lookup above is meaningful only when
    // both operands are nonzero. The mask is all ones exactly then, and all zeros otherwise,
    // which is the right answer for a product with zero.
    let both_nonzero = 0u8.wrapping_sub((a != 0) as u8 & (b != 0) as u8);
    EXP[exponent] & both_nonzero
}

/// The square of a `GF(2^8)` element, in the tower representation.
///
/// Doubling the exponent takes one lookup off [`mul`], which would compute the same value.
#[inline]
pub(crate) const fn square(a: u8) -> u8 {
    let exponent = 2 * LOG[a as usize] as usize;
    // Zero is masked out for the same reason as in [`mul`].
    let nonzero = 0u8.wrapping_sub((a != 0) as u8);
    EXP[exponent] & nonzero
}

/// The inverse of a `GF(2^8)` element, or `None` for zero.
///
/// `g^e · g^(255 − e) = g^255 = 1`, and the exponent `255 − e` lies in `1..=255`, which
/// [`EXP`] covers.
#[inline]
pub(crate) const fn try_inverse(a: u8) -> Option<u8> {
    if a == 0 {
        None
    } else {
        Some(EXP[255 - LOG[a as usize] as usize])
    }
}

#[cfg(test)]
mod tests {
    extern crate std;

    use std::println;

    use p3_field::{Field, PrimeCharacteristicRing};

    use super::*;
    use crate::BinaryField8;
    use crate::tower::TowerLevel;

    /// The tables as the powers of [`BinaryField8::GENERATOR`] define them, computed with the
    /// recursive tower product alone.
    fn derive_tables() -> ([u8; 256], [u8; 511]) {
        let mut log = [0u8; 256];
        let mut exp = [0u8; 511];

        let mut power = BinaryField8::ONE;
        for (e, slot) in exp.iter_mut().take(255).enumerate() {
            *slot = power.to_repr();
            log[power.to_repr() as usize] = e as u8;
            power = power.reference_mul(BinaryField8::GENERATOR);
        }
        assert_eq!(power, BinaryField8::ONE, "the generator has order 255");

        for e in 255..exp.len() {
            exp[e] = exp[e - 255];
        }

        (log, exp)
    }

    /// Every one of the `65_536` ordered pairs, against the recursive definition of the tower
    /// product. The tables are a rewriting of that product and must reproduce it exactly.
    #[test]
    fn the_table_product_agrees_with_the_recursive_one_on_every_pair() {
        for a in 0..=u8::MAX {
            for b in 0..=u8::MAX {
                let expected = BinaryField8::from_repr(a)
                    .reference_mul(BinaryField8::from_repr(b))
                    .to_repr();
                assert_eq!(mul(a, b), expected, "mul({a}, {b})");
            }
        }
    }

    #[test]
    fn the_table_square_agrees_with_the_recursive_product() {
        for a in 0..=u8::MAX {
            let x = BinaryField8::from_repr(a);
            assert_eq!(square(a), x.reference_mul(x).to_repr(), "square({a})");
        }
    }

    #[test]
    fn the_table_inverse_undoes_the_table_product() {
        assert_eq!(try_inverse(0), None);
        for a in 1..=u8::MAX {
            let inverse = try_inverse(a).expect("every nonzero element is invertible");
            assert_eq!(mul(a, inverse), 1, "inverse({a})");
        }
    }

    /// `LOG` and `EXP` are inverse bijections on the nonzero elements.
    #[test]
    fn the_tables_invert_each_other() {
        for (e, &power) in EXP.iter().enumerate().take(255) {
            assert_eq!(LOG[power as usize] as usize, e, "LOG[EXP[{e}]]");
        }
        for x in 1..=u8::MAX {
            assert_eq!(EXP[LOG[x as usize] as usize], x, "EXP[LOG[{x}]]");
        }
    }

    /// The generator has full order, so its `255` powers are the `255` nonzero elements, and
    /// the second period of `EXP` repeats the first.
    #[test]
    fn the_generator_powers_enumerate_every_nonzero_element() {
        let mut seen = [false; 256];
        for (e, &power) in EXP.iter().enumerate().take(255) {
            assert_ne!(power, 0, "no power of the generator is zero");
            assert!(!seen[power as usize], "EXP[{e}] repeats an earlier power");
            seen[power as usize] = true;
        }
        assert!(seen.iter().skip(1).all(|&hit| hit));
        assert!(!seen[0]);

        for e in 255..511 {
            assert_eq!(EXP[e], EXP[e - 255], "EXP[{e}]");
        }
    }

    #[test]
    fn the_pinned_tables_match_the_derivation() {
        let (log, exp) = derive_tables();
        assert_eq!(log, LOG);
        assert_eq!(exp, EXP);
    }

    /// Prints the tables in the form they are pinned above.
    ///
    /// Run with `cargo test -p p3-binary-field --release -- --ignored --nocapture`.
    #[test]
    #[ignore = "one-off derivation used to pin the LOG and EXP tables"]
    fn regenerate_tables() {
        let (log, exp) = derive_tables();
        assert_eq!(log, LOG);
        assert_eq!(exp, EXP);

        for value in log {
            println!("LOG {value}");
        }
        for value in exp {
            println!("EXP {value}");
        }
    }
}
